"""Batch 7 (EP31-EP35) editorial content: "Niat Baik yang Jadi Bumerang". Executed inside epdata.py, so EPS and WP come from there."""
RD7 = "Dibaca 9 Nov 2026"


def _b(rows):
    return {f"s{i+1}": r for i, r in enumerate(rows)}


def _ep(**k):
    k.setdefault("alts", [])
    return k


